    if (R.people) { const gk = R.people.groups.map((g) => g.id); const colors = {}, labels = {}; R.people.groups.forEach((g, i) => { colors[g.id] = Charts.groupColor(i); labels[g.id] = g.label; }); if ($('chFront')) { Charts.stackedBars($('chFront'), R.people.front, gk, { unit: 'persons/h', xLabel: (r) => r.h, xTick: (r, i) => i % 2 === 0, colors, labels, title: 'Who walks past the frontage' }); $('chFront').insertAdjacentHTML('afterbegin', '<h4>Who walks past the frontage (persons/h, by 15 min)</h4>'); } if ($('chOcc')) { Charts.stackedBars($('chOcc'), R.people.occAll, gk, { unit: 'people', xLabel: (r) => r.h, xTick: (r, i) => i % 2 === 0, colors, labels, title: 'People staying on the site' }); $('chOcc').insertAdjacentHTML('afterbegin', '<h4>People staying on the site (average present, by 15 min)</h4>'); } }
    if (ix.length) { Charts.groupedBars($('chIx'), ix, B && Pp ? ['base', 'prop'] : ['prop'], { unit: 's/veh', title: 'Control delay at nearby junctions', bands: [{ v: 35, label: 'LOS C/D' }, { v: 55, label: 'D/E' }] }); $('chIx').insertAdjacentHTML('afterbegin', '<h4>Junction delay</h4>'); }
    wire('btnCsv', 'click', () => download('sidewalks.csv', toCsv(Analysis.sidewalkRows(state.net, B, R, state.R), ['name', 'kind', 'frontage', 'w', 'base', 'prop', 'baseRate', 'rate', 'baseLos', 'los', 'wait']))); wire('btnCsv2', 'click', () => download('links.csv', toCsv(Analysis.linkRows(state.net, B, R, state.R), ['name', 'cls', 'lanes', 'cap', 'base', 'prop', 'baseVc', 'vc', 'baseDelay', 'delay', 'maxQ', 'blocked', 'baseLos', 'los'])));
    wire('btnJson', 'click', () => download('street-flow-summary.json', JSON.stringify({ site: state.site.addr, window: [state.params.t0, state.params.t1], baseline: kb, proposed: kp, walkshed: ws ? { w5: ws.w5.got, w10: ws.w10.got, area5: ws.w5.area, area10: ws.w10.area } : null }, (k, v) => (v && v.poly ? undefined : v), 1)));
